    pos = _MIN_MESSAGE_LEN
    for _ in range(qdcount):
        while True:
            if pos >= len(reply):
                return None
            length = reply[pos]
            kind = length & 0xC0
            if kind == 0xC0:
                if pos + 1 >= len(reply):
                    return None
                pos += 2
                break
            if kind != 0x00:
                return None
            pos += 1
            if length == 0:
                break
            if pos + length > len(reply):
                return None
            pos += length
        if pos + 4 > len(reply):
            return None
        pos += 4
    return pos


